import{a as e,i as t,r as n,t as r}from"./app-DllFuXBm.js";var i=JSON.parse(`{"path":"/guide/message.html","title":"消息管理","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1791121863000,"contributors":[{"name":"ShiroMizu","username":"","email":"ShiroMizuTan@163.com","commits":1}],"changelog":[{"hash":"166a3aafef6a84f2d36cd610c59ea02e9855f9e0","time":1791121863000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: add profile/avatar and message management pages"}]},"filePathRelative":"guide/message.md"}`),a={name:`message.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="消息管理" tabindex="-1"><a class="header-anchor" href="#消息管理"><span>消息管理</span></a></h1><h2 id="撤回" tabindex="-1"><a class="header-anchor" href="#撤回"><span>撤回</span></a></h2><table><thead><tr><th>指令</th><th>别名</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>撤回</code></td><td><code>撤回消息</code> / <code>收回</code></td><td><code>.撤回</code></td><td>撤回雪希在当前会话发出的最后一条消息</td></tr></tbody></table><div class="hint-container warning"><p class="hint-container-title">三个前提</p><ol><li><strong>只能在 QQ 群 / QQ 私聊里用</strong>，QQ 官方那边不支持</li><li>只能撤回<strong>雪希自己</strong>发的消息，撤不了别人的</li><li>要在<strong>同一个会话里</strong>发指令 —— 群里发就撤群里的，私聊发就撤私聊的</li></ol></div><p>撤回成功后<strong>不会有任何回复</strong>，因为撤回本身就是回应。失败时会告诉你原因。</p><h2 id="常见问题" tabindex="-1"><a class="header-anchor" href="#常见问题"><span>常见问题</span></a></h2><p><strong>Q：提示「没有可撤回的消息」？</strong> 可能是这几种情况：</p><ul><li>雪希在这个会话里还没发过消息</li><li>要撤的那条已经被撤过了</li><li>距离发出太久，已经超过撤回时限</li></ul><p><strong>Q：能撤回别人发的消息吗？</strong> 不能，只能撤回雪希自己发的。</p><p><strong>Q：为什么要在同一个会话里发？</strong> 撤回指令只认当前所在的会话。在 A 群发 <code>.撤回</code>，撤的是 A 群里雪希最后一条消息，不会影响 B 群。</p><h2 id="自动撤回" tabindex="-1"><a class="header-anchor" href="#自动撤回"><span>自动撤回</span></a></h2><p>色图（<code>.setu</code>）发出来的图片，可以设置成<strong>过一会儿自动撤回</strong>，避免刷屏。</p><p>默认是关着的，需要的话找管理员开一下，可以设置延迟多少秒撤回。</p><div class="hint-container tip"><p class="hint-container-title">目前只有色图支持</p><p>其他指令发出的图片不会自动撤回，想撤的话手动发 <code>.撤回</code> 就行。</p></div>`,14)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};